/* ------------------------------ chave pix ------------------------------ */
/* A API moderna só existe em contexto seguro (https). Sem ela, cai no
   textarea escondido — que ainda funciona no celular e no arquivo local. */
async function copiarTexto(texto){
  try{
    if(navigator.clipboard && window.isSecureContext){
      await navigator.clipboard.writeText(texto);
      return true;
    }
  }catch(e){ /* segue para o plano B */ }
  try{
    const ta = document.createElement('textarea');
    ta.value = texto;
    ta.setAttribute('readonly','');
    ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0';
    document.body.appendChild(ta);
    ta.select();
    ta.setSelectionRange(0, texto.length);        // iOS só copia com o intervalo explícito
    const ok = document.execCommand('copy');
    ta.remove();
    return ok;
  }catch(e){ return false; }
}

let voltaBotaoPix;
$('btnCopiarPix').addEventListener('click', async ()=>{
  const btn = $('btnCopiarPix');
  const ok = await copiarTexto($('pixChave').textContent.trim());
  if(ok){
    btn.textContent = 'Chave copiada';
    btn.classList.add('feito');
    avisar('Chave PIX copiada. Cole no aplicativo do seu banco.');
    clearTimeout(voltaBotaoPix);
    voltaBotaoPix = setTimeout(()=>{
      btn.textContent = 'Copiar chave';
      btn.classList.remove('feito');
    }, 2600);
  }else{
    /* Sem cópia automática, deixa a chave selecionada para copiar na mão. */
    const sel = window.getSelection();
    const faixa = document.createRange();
    faixa.selectNodeContents($('pixChave'));
    sel.removeAllRanges();
    sel.addRange(faixa);
    avisar('Seu navegador bloqueou a cópia. A chave está selecionada — copie manualmente.','erro');
  }
});

